    def __init__(self):
        pass

    @property
    @abstractmethod
    def data(self):
        """The stored dataset."""
        pass

    @property
    @abstractmethod
    def mask(self):
        """Mask for the dataset.

        Masks should follow the ``numpy`` convention that **valid** data points
        are marked by ``False`` and **invalid** ones with ``True``.
        """
        return None

    @property
    @abstractmethod
    def unit(self):
        """Unit for the dataset."""
        return None

    @property
    @abstractmethod
    def wcs(self):
        """World coordinate system (WCS) for the dataset."""
        return None

